// Nilad F3 — keep only pending orders older than $env.PENDING_HOURS that are not
// yet marked in static data sd.keys ('f3:<id>'). Env: PENDING_HOURS.
// Input: ONE item whose json is the orders ARRAY returned by the WC REST API.
// Output: one item per survivor { orderId, email, customerName, total, ageHours,
//          hasEmail } — or [{ json: { none: true } }] if nothing qualifies.
const payload = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.keys = Array.isArray(sd.keys) ? sd.keys : [];
const rawHours = Number($env.PENDING_HOURS);
const thresholdMs = Number.isFinite(rawHours) && rawHours > 0 ? rawHours * 3600 * 1000 : NaN;
const orders = Array.isArray(payload) ? payload : null;
if (!orders || Number.isNaN(thresholdMs)) {
  return [{ json: { none: true } }];
}
const now = Date.now();
const survivors = [];
for (const o of orders) {
  if (!o || o.status !== 'pending') continue;
  const id = o.id;
  if (id === undefined || id === null) continue;
  const created = Date.parse(o.date_created);
  if (Number.isNaN(created)) continue;
  const ageMs = now - created;
  if (!(ageMs > thresholdMs)) continue;
  if (sd.keys.includes('f3:' + id)) continue;
  const b = o.billing || {};
  const email = typeof b.email === 'string' ? b.email.trim() : '';
  const customerName = [b.first_name, b.last_name]
    .filter((p) => p && String(p).trim() !== '')
    .map((p) => String(p).trim())
    .join(' ');
  survivors.push({
    json: {
      orderId: id,
      email,
      customerName,
      total: o.total,
      ageHours: Math.floor(ageMs / 3600000),
      hasEmail: email !== '',
    },
  });
}
return survivors.length > 0 ? survivors : [{ json: { none: true } }];

// Nilad F3 — build the Arabic customer reminder email + owner Telegram line.
// Env: $env.PENDING_HOURS (threshold quoted in the email body).
// Input: one item { orderId, email, customerName, total, ageHours, hasEmail, none }
//        — or the passthrough { none: true }.
// Output: same fields + emailSubject / emailText / tgText (all user text escaped);
//         the { none: true } case passes through unchanged.
const j = $input.first().json;
if (j && j.none === true) {
  return [{ json: {
    // n8n 2.41 blocks $env in node expressions (Code nodes may read it), so
    // the Telegram HTTP node gets its credentials from this item instead.
    tgToken: $env.TELEGRAM_BOT_TOKEN || '',
    tgChatId: $env.TELEGRAM_CHAT_ID || '', none: true } }];
}
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const id = esc(j.orderId);
const name = esc(j.customerName || 'عزيزنا العميل');
const total = esc(j.total);
const age = esc(j.ageHours);
const hours = esc($env.PENDING_HOURS);
const emailSubject = 'طلبك المعلق #' + id + ' بانتظارك';
const emailText = [
  'مرحباً ' + name + ',',
  '',
  'طلبك رقم #' + id + ' ما زال معلقاً منذ ' + age + ' ساعة (أكثر من ' + hours + ' ساعة)، وإجماليه ' + total + ' ج.م.',
  '',
  'يرجى إتمام الدفع لتأكيد الطلب، وإن كان الدفع عند الاستلام (COD) فيرجى تأكيد توفرك لاستلامه حتى لا يُلغى الطلب.',
  '',
  'شكراً لتسوقك من نيلاد.',
].join('\n');
const tgText = '🕓 طلب معلق قديم #' + id + ' — ' + name + ' — ' + total + ' ج.م — منذ ' + age + ' ساعة';
return [{
  json: {
    orderId: j.orderId,
    email: j.email,
    customerName: j.customerName,
    total: j.total,
    ageHours: j.ageHours,
    hasEmail: j.hasEmail,
    emailSubject,
    emailText,
    tgText,
    none: false,
  },
}];

// Nilad F3 — mark one order as reminded (idempotency write, sd.keys capped at 500).
// Env: none. Input: ONE item { orderId, ... } — output is the item passthrough.
const sd = $getWorkflowStaticData('global');
sd.keys = Array.isArray(sd.keys) ? sd.keys : [];
const j = $input.first().json;
const key = 'f3:' + j.orderId;
if (!sd.keys.includes(key)) sd.keys.push(key);
if (sd.keys.length > 500) sd.keys.splice(0, sd.keys.length - 500);
return [{ json: { ...j } }];
